{
  "name": "化学气相沉积（CVD）工艺控制台",
  "name_en": "CVD process controller",
  "manufacturer": "UNILAB",
  "description": "用于控制化学气相沉积（CVD）反应器的物理控制台。设备面向薄膜沉积实验，包含多路气体流量通道（用于独立控制多种进气）、温度加热/设定功能、工艺配方的保存与加载、启停工艺的机械/电子控制，以及实时过程曲线显示与监控。用于在受控气体和温度条件下按配方执行沉积工艺并记录关键过程参数。",
  "description_en": "Physical control console for a chemical vapor deposition (CVD) reactor used to deposit thin films. The system provides multiple gas flow channels (independent control of several input gases), temperature/heater setpoint control, facilities to save and load process recipes, start/stop execution of recipes, and real‑time plotting/monitoring of process variables. Used to run and monitor deposition recipes under controlled gas and temperature conditions.",
  "actions": [
    {
      "action_name": "auto-return_ui_fields",
      "description": "返回界面中各字段的当前值（用于更新或读取UI参数）",
      "description_en": "Return current values of the UI fields (for updating or reading UI parameters)"
    },
    {
      "action_name": "auto-save_recipe",
      "description": "将当前界面参数保存为工艺配方文件，包含元数据（作者、创建日期）、气体列标签等",
      "description_en": "Save current UI parameters to a recipe file, including metadata (author, creation date) and gas column labels"
    },
    {
      "action_name": "auto-open_recipe",
      "description": "打开并加载工艺配方文件，将文件中的参数与元数据显示到界面并设置气体列标签",
      "description_en": "Open and load a recipe file, populate UI fields and metadata display, and set gas column labels from the file"
    },
    {
      "action_name": "auto-update_plot",
      "description": "更新实时过程曲线（例如随时间变化的气体流量），在曲线中移除旧点并追加新点",
      "description_en": "Update real‑time process plots (e.g., gas flow vs. time) by removing old points and appending new values"
    },
    {
      "action_name": "auto-start_recipe",
      "description": "开始运行所选工艺配方，启动后台执行任务并将界面状态更新为运行",
      "description_en": "Start executing the selected recipe, launch the background run task, and update the UI status to RUNNING"
    },
    {
      "action_name": "auto-stop_recipe",
      "description": "停止正在运行的工艺流程并将配方状态设为停止",
      "description_en": "Stop a running recipe/process and set the recipe status to stopped"
    },
    {
      "action_name": "auto-apply_setpoints",
      "description": "设置 气体流量和温度设定值",
      "description_en": "set gas flow and temperature setpoints"
    }
  ],
  "tag_hints": [
    "chemical vapor deposition (CVD)",
    "mass flow controllers",
    "temperature control",
    "process recipe management",
    "real-time plotting",
    "thin-film deposition",
    "gas delivery"
  ]
}
